const listening=new ListeningSession({team,media:listeningMedia,getPlayer:()=>({trackId:visibleTrack(currentId)?.id||null,private:isLocalTrack(state,currentId),allowListen:playbackPrivacy(state,team.user?.id,visibleTrack(currentId)).listen,position:audio.currentTime||0,playing:!audio.paused}),onRemote:syncRemotePlayer,onChange:()=>{if(!listening.followRoom&&typeof studioGuest!=='undefined'&&studioGuest.enabled)studioGuest.stop();if(!listening.followRoom&&synchronized.room)synchronized.reset();if(currentView==='listen')render();for(const key of ['previous','next','seek','shuffle','repeat'])$('#'+key).disabled=!!listening.followRoom;updateDesktopPlayer();},onError:e=>{if(e.status===410)audio.pause();fail(e);}});
const musicbox=new MusicboxLinks({client:team.backend.client,getOwner:()=>team.user,getCatalog:()=>team.baseline||{},getBlob:key=>team.fetchBlob(key),ensureSynced:()=>persist(false),makeAlbum:buildAlbumMP3});
