const toast=(message,error=false)=>{const box=$('#toast');box.textContent=message;box.hidden=false;box.classList.toggle('danger-text',error);clearTimeout(toast.timer);toast.timer=setTimeout(()=>box.hidden=true,error?9000:7000);qol?.appendUndo();if(error&&/(Verbindung|erreichbar|Netz|fetch|HTTP|Supabase|Spotify|Anfragelimit)/i.test(message)&&!box.querySelector('[data-qol=retry]'))box.insertAdjacentHTML('beforeend','<button class="button ghost compact" data-qol="retry">Verbindung prüfen</button>');};
const fail=e=>{console.error(e?.message||e);toast(e?.message||'Das hat nicht geklappt. Bitte erneut versuchen.',true);};
function persistLocal(renderAgain=true){if(!storageReady)return Promise.reject(new Error('Die Mediathek wurde nicht vollständig geladen. Bitte zuerst die Wiederherstellung prüfen.'));qol?.changed(upgrade?.capture());const copy=structuredClone(state);saveChain=saveChain.catch(()=>{}).then(()=>saveState(copy));return saveChain.then(()=>{if(renderAgain)render();});}
function persist(renderAgain=true){if(!storageReady)return Promise.reject(new Error('Die Mediathek wurde nicht vollständig geladen. Bitte zuerst die Wiederherstellung prüfen.'));qol?.changed(upgrade?.capture());const copy=structuredClone(state);saveChain=saveChain.catch(()=>{}).then(async()=>{await saveState(copy);if(team.active)await team.push(copy);});return saveChain.then(()=>{if(renderAgain)render();});}
async function objectURL(key){if(!key)return '';if(nextStudio?.received().some(t=>t.blobId===key))return nextStudio.sharing.objectURL(key);const local=state.localTracks.find(t=>t.blobId===key||t.coverBlobId===key);if(local&&local.ownerId!==team.user?.id)return '';if(urlCache.has(key))return urlCache.get(key);const blob=await (local?getBlob(key):team.fetchBlob(key));if(!blob)return '';const url=URL.createObjectURL(blob);urlCache.set(key,url);return url;}
function releaseURL(key){if(urlCache.has(key)){URL.revokeObjectURL(urlCache.get(key));urlCache.delete(key);}}
function hydrateImages(root=document){for(const img of root.querySelectorAll('[data-blob]'))objectURL(img.dataset.blob).then(url=>{if(url&&img.isConnected)img.src=url;}).catch(fail);}
function cover(album,cls='cover'){return `<div class="${cls}">${album?.coverBlobId?`<img data-blob="${h(album.coverBlobId)}" src="assets/logo.svg" alt="Cover: ${h(album.title)}">`:'<img class="cover-mark" src="assets/logo.svg" alt=""><span class="cover-caption">NEON TRINITY</span>'}</div>`;}
function empty(title,description,action,button,symbol='♫',small=false){return `<div class="empty ${small?'small':''}"><span class="empty-symbol">${symbol}</span><h3>${title}</h3><p>${description}</p>${action?`<button class="button ${small?'ghost':'primary'}" data-action="${action}">${button}</button>`:''}</div>`;}
function heading(title,description,action,button){return `<div class="page-heading"><div><h1>${title}</h1><p>${description}</p></div>${action?`<button class="button primary" data-action="${action}">＋ ${button}</button>`:''}</div>`;}
function uploadZone(){return '<div class="upload-zone" data-action="import" role="button" tabindex="0"><span class="upload-icon">↥</span><div><strong>Dein Sound gehört hierher.</strong><p>MP3s hier ablegen oder Dateien auf deinem Computer auswählen · bis 48 MiB pro Song</p></div><span class="button ghost compact">Dateien auswählen</span></div>';}
function playlistsForView(){return [...visiblePlaylists(state,team.user?.id),...ownLocalPlaylists(state,team.user?.id)];}
function allTracks(){return [...availableTracks(state,team.user?.id),...(nextStudio?.received()||[])];}
function visibleTrack(key){return allTracks().find(t=>t.id===key);}
function playlistLabel(p){return p.visibility==='local'?'Nur auf diesem Gerät':p.visibility==='private'?'Nur für mich':'Für die Band';}
function filteredTracks(){const tracks=currentView==='local'?ownLocalTracks(state,team.user?.id):state.tracks;return qol?qol.sorted(nextStudio?nextStudio.filter(tracks,search):tracks,currentView,nextStudio?'':search):tracks.filter(t=>`${t.title} ${t.artist} ${t.voices} ${t.genre||''}`.toLowerCase().includes(search.toLowerCase()));}
function trackTable(tracks,context='library') {
  if(!tracks.length&&context==='local')return empty(search?'Keine Treffer':'Deine private Musiksammlung.',search?'Versuch einen anderen Suchbegriff.':'Importiere eigene MP3s. Deine Sammlung bleibt auf diesem Gerät deinem Discord-Konto zugeordnet. Laufende Songs kannst du über deinen Hörlink teilen.',search?null:'import-local','Private MP3s importieren');
  if(!tracks.length)return empty(search?'Keine Treffer':'Noch ist es hier still.',search?'Versuch einen anderen Suchbegriff.':'Importiere deine ersten MP3s und mach das Studio zu eurem Soundarchiv.',search?null:'import','MP3s importieren');
  return `<div class="table-wrap"><table class="track-table"><thead><tr><th>#</th><th>Titel</th><th>Stimmen</th><th>Dauer</th><th></th></tr></thead><tbody>${tracks.map((t,i)=>`<tr data-musicbox-kind="track" data-musicbox-id="${h(t.id)}" tabindex="0" class="${t.id===currentId?'selected-track':''}"><td class="number">${String(i+1).padStart(2,'0')}</td><td><div class="song-cell"><button class="song-art" data-action="play-track" data-id="${h(t.id)}" data-context="${h(context)}" title="Abspielen" aria-label="${h(t.title)} abspielen">${t.coverBlobId?`<img data-blob="${h(t.coverBlobId)}" src="assets/logo.svg" alt="">`:'▶'}</button><div><strong>${h(t.title)}</strong><small>${h(t.artist)}</small></div></div></td><td><span class="tag">${h(t.visibility==='local'?'PRIVAT · LOKAL':t.voices||'DEX · NIX · JAX')}</span></td><td class="duration">${time(t.duration)}</td><td><div class="row-actions"><button class="icon-button" data-action="add-to-playlist" data-id="${h(t.id)}" title="Zu Playlist hinzufügen" aria-label="Zu Playlist hinzufügen">＋</button><button class="icon-button" data-action="edit-track" data-id="${h(t.id)}" title="Song bearbeiten" aria-label="Song bearbeiten">⋯</button></div></td></tr>`).join('')}</tbody></table></div>`;
}
function albumCard(a){return `<article class="album-card" data-musicbox-kind="album" data-musicbox-id="${h(a.id)}" tabindex="0"><a href="#album/${h(a.id)}">${cover(a)}<h3>${h(a.title)}</h3></a><p>${h(a.year)} · ${a.trackIds.length} Songs · ${time(duration(a.trackIds,state.tracks))}</p><div class="card-actions"><span class="badge ${state.published[a.id]?'live':''}">${state.published[a.id]?'VERÖFFENTLICHT':'ENTWURF'}</span><button class="text-link" data-action="edit-album" data-id="${h(a.id)}">Bearbeiten ↗</button></div></article>`;}
function eventCard(event,compact=false){const date=new Date(event.date),valid=!isNaN(date),playlist=state.playlists.find(p=>p.id===event.playlistId);return `<article class="event-card"><div class="date-box"><strong>${valid?date.getDate():'–'}</strong><small>${valid?date.toLocaleDateString('de-DE',{month:'short'}):'OFFEN'}</small></div><div class="event-info"><h3>${h(event.title)}</h3><p>${valid?date.toLocaleDateString('de-DE',{weekday:'short',year:'numeric',hour:'2-digit',minute:'2-digit'}):'Termin noch offen'}<br>${h(event.location||'Ort folgt')} · ${playlist?`${playlist.trackIds.length} Songs / ${time(duration(playlist.trackIds,state.tracks))}`:'Setlist noch offen'}</p></div><div class="event-controls">${playlist?`<button class="icon-button" data-action="play-playlist" data-id="${h(playlist.id)}" title="Setlist abspielen" aria-label="Setlist abspielen">▶</button>`:''}<button class="icon-button" data-action="edit-event" data-id="${h(event.id)}" title="Auftritt bearbeiten" aria-label="Auftritt bearbeiten">⋯</button></div></article>`;}
function overview(){const next=[...state.events].filter(e=>new Date(e.date).getTime()>=Date.now()-86400000).sort((a,b)=>a.date.localeCompare(b.date))[0];return `${heading('Willkommen im Studio.','Alles für euren Sound. Alles für eure nächste Show.')}<section class="hero"><div class="live-tag"><i class="status-dot"></i> DEX · NIX · JAX</div><div class="hero-copy"><div class="eyebrow">THIS IS YOUR FREQUENCY.</div><h2>Drei Stimmen.<br><span>Ein Puls.</span></h2><p>Von der ersten Idee bis zur letzten Zugabe.<br>Euer Sound hat jetzt ein Zuhause.</p><div class="hero-actions"><button class="button primary" data-action="import">↥ Musik importieren</button><a class="button ghost" href="#events">Nächste Show planen ↗</a></div></div><div class="hero-art" aria-hidden="true"><img src="assets/neon-trinity.png" alt=""><span class="orbit-label">NEON TRINITY</span></div></section><div class="stats-grid">${[['library',state.tracks.length,'Songs in der Mediathek'],['albums',state.albums.length,'Eigene Alben'],['playlists',playlistsForView().length,'Playlists & Setlists'],['events',state.events.length,'Geplante Auftritte']].map(([key,value,label])=>`<a class="stat" href="#${key}"><div class="stat-icon">${icon(key)}</div><div><strong>${value.toString().padStart(2,'0')}</strong><small>${label}</small></div></a>`).join('')}</div><div class="overview-columns"><section><div class="section-header"><h2>Eure Alben</h2><a class="text-link" href="#albums">Alle ansehen ↗</a></div>${state.albums.length?`<div class="cards">${state.albums.slice(-2).reverse().map(albumCard).join('')}</div>`:empty('Der nächste Release beginnt hier.','Pack eure Songs in ein Album, gib ihm ein Cover und teile es mit der Welt.','new-album','Erstes Album erstellen','◉',true)}</section><section><div class="section-header"><h2>Auf die Bühne.</h2><a class="text-link" href="#events">Auftritte ↗</a></div>${next?eventCard(next,true):empty('Die nächste Show wartet.','Plane euren Auftritt und stell die passende Setlist aus der Mediathek zusammen.','new-event','Auftritt planen','⚡',true)}</section></div><section><div class="section-header" id="recent-header"><h2>Zuletzt hinzugefügt</h2><a class="text-link" href="#library">Zur Mediathek ↗</a></div>${state.tracks.length?trackTable([...state.tracks].reverse().slice(0,5),'recent'):uploadZone()}</section>`;}
function library(){return `${heading('Euer Soundarchiv.','Alle Songs an einem Ort. Bereit für Alben, Playlists und die Bühne.','import','MP3s importieren')}${uploadZone()}<div class="toolbar"><span class="eyebrow">MEDIATHEK</span><span class="badge">${filteredTracks().length} SONGS · ${time(duration(filteredTracks().map(t=>t.id),state.tracks))}</span></div>${trackTable(filteredTracks())}`;}
function localLibrary(){const owner=team.user?.id;if(!owner)return `${heading('Nur für dich. Auf deinem Gerät.','Eine eigene Mediathek für Musik außerhalb von Neon Trinity.')}<section class="panel settings-section"><h2>Mit deinem Discord-Konto öffnen.</h2><p class="notice">Deine lokalen Songs sind an dein Konto gebunden. Melde dich an, um nur deine Sammlung zu sehen.</p><a class="button primary" href="#team">Mit Discord anmelden ↗</a></section>`;
  const lists=ownLocalPlaylists(state,owner);return `${heading('Deine Musik. Dein Raum.','Nur für dein Discord-Konto auf diesem Gerät. Eine Bandkopie erstellst du ausdrücklich per Rechtsklick.','import-local','Private MP3s importieren')}<div class="note private-library-note"><strong>Privat & lokal</strong><br>Deine Sammlung und lokalen Playlists bleiben nur für dich sichtbar. Laufende Songs erscheinen als Discord-Höraktivität. Bei eingeschaltetem automatischem Mithören wird nur die aktuelle MP3 vorübergehend für deinen Hörlink bereitgestellt; ausschalten kannst du das unter Team & Discord.</div><div class="upload-zone" role="button" tabindex="0" data-action="import-local"><span class="upload-icon">↥</span><div><strong>Eigene MP3s lokal hinzufügen.</strong><p>Dateien hier ablegen oder auswählen · bis 48 MiB pro Song</p></div><span class="button ghost compact">Dateien auswählen</span></div><div class="toolbar"><span class="eyebrow">DEINE LOKALE MEDIATHEK</span><span class="badge">${ownLocalTracks(state,owner).length} SONGS</span><button class="button ghost compact" data-action="new-local-playlist">＋ Lokale Playlist</button></div>${trackTable(filteredTracks(),'local')}<div class="section-header local-playlist-heading"><h2>Deine lokalen Playlists</h2></div>${lists.length?`<div class="grid-two">${lists.map(p=>`<article class="playlist-card"><div class="playlist-icon">☷</div><div><h3>${h(p.title)}</h3><span class="badge">Nur auf diesem Gerät</span><p>${p.trackIds.length} Songs · ${time(duration(p.trackIds,allTracks()))}</p><button class="text-link" data-action="play-playlist" data-id="${h(p.id)}">▶ Abspielen</button> <button class="text-link" data-action="edit-playlist" data-id="${h(p.id)}">Bearbeiten ↗</button></div></article>`).join('')}</div>`:'<p class="notice">Lokale Playlists können deine privaten MP3s und Band-Songs enthalten.</p>'}`;
}
function albumsView(){const list=state.albums.filter(a=>`${a.title} ${a.description}`.toLowerCase().includes(search.toLowerCase()));return `${heading('Musik, die bleibt.','Deine Alben. Dein Cover. Ein eigener Link für jeden Release.','new-album','Album erstellen')}${list.length?`<div class="cards">${list.map(albumCard).join('')}<button class="card-add" data-action="new-album"><span>＋</span>Neues Album</button></div>`:empty('Mach aus Songs einen Release.','Wähle Titel aus deiner Mediathek, lade ein Cover hoch und gestalte eure eigene Albumseite.','new-album','Album erstellen','◉')}`;}
function albumDetail(key){const a=state.albums.find(x=>x.id===key);if(!a)return empty('Album nicht gefunden.','Gehe zurück zur Albumübersicht.');const tracks=a.trackIds.map(k=>state.tracks.find(t=>t.id===k)).filter(Boolean);return `<div class="toolbar"><a class="text-link" href="#albums">← Zurück zu den Alben</a></div><section class="album-detail-hero" data-musicbox-kind="album" data-musicbox-id="${h(a.id)}" tabindex="0">${cover(a)}<div><div class="eyebrow">NEON TRINITY · ALBUM</div><h1>${h(a.title)}</h1><p>${h(a.year)} · ${tracks.length} Songs · ${time(duration(a.trackIds,state.tracks))}<br>${h(a.description||'')}</p><div class="hero-actions"><button class="button primary" data-action="play-album" data-id="${h(a.id)}" ${tracks.length?'':'disabled'}>▶ Abspielen</button><button class="button ghost" data-action="edit-album" data-id="${h(a.id)}">Bearbeiten</button><button class="button ghost" data-action="publish-album" data-id="${h(a.id)}">↗ ${state.published[a.id]?'Aktualisieren & teilen':'Album veröffentlichen'}</button></div></div></section>${state.published[a.id]?`<div class="note"><strong>Albumseite vorbereitet / veröffentlicht</strong><br><a class="public-link" href="${h(albumLink(a.id,state.settings))}" target="_blank" rel="noopener">${h(albumLink(a.id,state.settings))}</a> <button class="text-link" data-action="copy-link" data-id="${h(a.id)}">Link kopieren</button><br>Freigegebene Alben werden direkt aus Supabase geladen. Eure Player-Website muss einmal bereitgestellt sein.</div>`:''}${trackTable(tracks,`album/${a.id}`)}`;}
function playlistsView(){const list=playlistsForView().filter(p=>`${p.title} ${p.description}`.toLowerCase().includes(search.toLowerCase()));return `${heading('Die richtige Reihenfolge.','Playlists für jeden Moment. Setlists für jede Show.','new-playlist','Playlist erstellen')}${list.length?`<div class="grid-two">${list.map(p=>`<article class="playlist-card"><div class="playlist-icon">☷</div><div><h3>${h(p.title)}</h3><span class="badge">${playlistLabel(p)}</span><p>${p.trackIds.length} Songs · ${time(duration(p.trackIds,allTracks()))}</p><button class="text-link" data-action="play-playlist" data-id="${h(p.id)}">▶ Abspielen</button> <button class="text-link" data-action="edit-playlist" data-id="${h(p.id)}">Bearbeiten ↗</button></div></article>`).join('')}</div>`:empty('Gib eurer Show einen Flow.','Stell Songs aus der Mediathek zusammen, ändere ihre Reihenfolge und verknüpfe die Playlist mit einem Auftritt.','new-playlist','Erste Playlist erstellen','☷')}`;}
function eventsView(){const list=[...state.events].filter(e=>`${e.title} ${e.location}`.toLowerCase().includes(search.toLowerCase())).sort((a,b)=>a.date.localeCompare(b.date));return `${heading('Bis zur letzten Zugabe.','Auftritte planen, Setlists zuordnen und bereit für die Bühne sein.','new-event','Auftritt planen')}${list.length?`<div class="event-list">${list.map(e=>eventCard(e)).join('')}</div>`:empty('Wann ist eure nächste Show?','Trag Datum, Uhrzeit und Ort ein. Die passende Setlist wählst du aus euren Playlists.','new-event','Ersten Auftritt planen','⚡')}`;}
