async function promoteLocalTrack(trackId){if(upgrade?.live.enabled&&upgrade.live.locked)throw new Error('Bearbeitung ist im Bühnenmodus gesperrt.');if(promoting)throw new Error('Eine Bandkopie wird bereits vorbereitet.');promoting=true;const owner=team.user?.id;try{if(!team.active)throw new Error('Bitte zuerst mit dem Discord-Bandkonto anmelden.');const result=await copyLocalToBand({state,owner,trackId,getOwner:()=>team.user,getBlob,putBlob,deleteBlob});await persist();toast(result.existing?'Dieser Song ist bereits in der Bandmediathek.':'Eigene Kopie in der Bandmediathek gespeichert.');}finally{promoting=false;}}
function showModal(content){modalOwner=null;$('#modal-content').innerHTML=content;const dialog=$('#modal');if(!dialog.open)dialog.showModal();hydrateImages(dialog);dialog.scrollTop=0;}
function closeModal(){$('#modal').close();$('#modal-content').innerHTML='';modalOwner=null;}
async function confirmAction(title,description,button,onConfirm){const previousOwner=modalOwner;showModal(`<h2>${h(title)}</h2><p class="subtitle">${h(description)}</p><div class="form-actions"><button class="button ghost" id="cancel-confirm">Abbrechen</button><button class="button danger" id="confirm-action">${h(button)}</button></div>`);modalOwner=previousOwner;$('#cancel-confirm').onclick=closeModal;$('#confirm-action').onclick=async e=>{e.currentTarget.disabled=true;try{await onConfirm();closeModal();}catch(err){fail(err);if($('#confirm-action'))$('#confirm-action').disabled=false;}};}
async function getDuration(file){return new Promise((resolve,reject)=>{const a=new Audio();const url=URL.createObjectURL(file);let timer;const finish=(error)=>{clearTimeout(timer);const d=a.duration;a.removeAttribute('src');a.load();URL.revokeObjectURL(url);error?reject(error):resolve(d);};a.onloadedmetadata=()=>{if(!Number.isFinite(a.duration)||a.duration<=0)finish(new Error('Die Audiodauer konnte nicht gelesen werden.'));else finish();};a.onerror=()=>finish(new Error('Die Datei ist keine lesbare MP3.'));timer=setTimeout(()=>finish(new Error('Das Lesen der MP3 hat zu lange gedauert.')),20000);a.src=url;});}
