  if(upgrade?.live.enabled&&upgrade.live.locked)throw new Error('Bearbeitung ist im Bühnenmodus gesperrt.');if(importing)throw new Error('Ein Import läuft bereits.');const owner=team.user?.id;if(options.expectedOwner&&options.expectedOwner!==owner)throw new Error('Das Discord-Konto wurde gewechselt.');if(local&&!owner)throw new Error('Bitte zuerst mit Discord anmelden, um deine private lokale Mediathek zu öffnen.');
