function addToPlaylist(key){const track=visibleTrack(key);if(!track)return;const local=track.visibility==='local',owner=team.user?.id,choices=playlistsForView().filter(p=>!local||p.visibility==='local');if(!choices.length)return groupForm('playlist',null,key);showModal(`<h2>Zur Playlist hinzufügen.</h2><p class="subtitle">${local?'Private Songs bleiben in deinen lokalen Playlists.':'Wähle die passende Playlist.'}</p><div class="selection-list">${choices.map(p=>`<button class="track-choice" data-add-playlist="${h(p.id)}"><span>${h(p.title)}</span><small>${playlistLabel(p)} · ${p.trackIds.length} Songs</small></button>`).join('')}</div><div class="form-actions"><button id="new-from-song" class="button primary">＋ Neue Playlist</button></div>`);if(local)modalOwner=owner;$('#new-from-song').onclick=()=>groupForm('playlist',null,key);for(const btn of document.querySelectorAll('[data-add-playlist]'))btn.onclick=async()=>{const p=playlistsForView().find(x=>x.id===btn.dataset.addPlaylist);if(!p||local&&p.visibility!=='local')throw new Error('Private Songs können nur in lokale Playlists.');if(p.ownerId&&p.ownerId!==team.user?.id)throw new Error('Das Konto wurde gewechselt.');if(!p.trackIds.includes(key)){if(p.visibility==='private')await team.savePrivate({...p,trackIds:[...p.trackIds,key]});else p.trackIds.push(key);}await (p.ownerId?persistLocal():persist());closeModal();toast('Song zur Playlist hinzugefügt.');};}
