  if(document.activeElement!==$('#seek'))$('#seek').value=p.duration?p.position/p.duration*100:0;
  if(document.activeElement!==$('#volume')&&p.volume!=null)$('#volume').value=p.volume;
  for(const [key,allowed] of [['play-pause',p.canToggle],['previous',p.canPrevious],['next',p.canNext],['seek',p.canSeek],['volume',p.canVolume],['shuffle',p.canShuffle],['repeat',p.canRepeat]])$('#'+key).disabled=!allowed;
  $('#shuffle').setAttribute('aria-pressed',String(p.shuffle));$('#repeat').setAttribute('aria-pressed',String(p.repeat!=='off'));$('#repeat').title=repeatLabel(p.repeat);$('#repeat').setAttribute('aria-label',repeatLabel(p.repeat));$('#repeat').textContent=p.repeat==='track'?'↻¹':'↻';
  const eq=$('#dock-equalizer');if(eq){eq.hidden=!state.appearance.player.equalizerOpen;if(eq.dataset.source!==p.source||!eq.innerHTML){eq.dataset.source=p.source;eq.innerHTML=equalizerView(state.appearance.equalizer,p.source);bindPlayerSettings(eq);}}
  const share=$('#player-sharing');if(share)share.disabled=!p.title||['spotify','listen'].includes(p.source)||visibleTrack(currentId)?.visibility==='shared';
  const button=$('#equalizer-toggle');if(button)button.setAttribute('aria-expanded',String(state.appearance.player.equalizerOpen));
  const editor=$('#equalizer-settings');if(editor&&editor.dataset.source!==p.source){editor.dataset.source=p.source;editor.innerHTML=equalizerView(state.appearance.equalizer,p.source);bindPlayerSettings(editor);}
