async function playerCommand(input){
  const p=unifiedPlayback();let c=input?.command;if(['backward','forward','mute'].includes(c)){if(c==='mute')await qol?.mute();else await qol?.seek(c==='backward'?-10:10);return;}
  if(c==='listen-stop'){automaticSuppressed=true;await listening.leave();updateDesktopPlayer();return;}
  if(c==='pause'||c==='resume'){if((c==='pause')===p.paused)return;c='toggle';}
  if(c==='queue-move'){if(p.source==='spotify'||p.source==='listen')return;upgrade.moveQueue(Number(input.value?.from),Number(input.value?.to));return;}
  if(c==='queue-next'){if(input.value?.source!==p.source)return;upgrade.playNext(input.value.id);return;}
  if(c==='queue-save'){location.hash='studio/queue';render();return;}
  if(c==='open-spotify'){if(p.source==='spotify')window.open(spotify.playback?.url||'https://open.spotify.com','_blank','noopener');return;}
  if(c==='queue-more'){if(p.source==='spotify')await spotify.loadQueue(spotify.queuePlaylist?.id,true);updateDesktopPlayer();return;}
  if(c==='queue-play'){if(input.value?.source!==p.source)throw new Error('Die Musikquelle wurde gewechselt. Bitte die Titelliste erneut öffnen.');if(p.source==='spotify'){const row=spotify.queueItems.find(t=>'spotify-'+t.index===input.value.id);if(!row?.playable||!spotify.queuePlaylist)return;await spotify.command({action:'playlist',playlistId:spotify.queuePlaylist.id,index:row.index,deviceId:spotify.playback?.device?.id||spotify.device});}else{if(!queue.includes(input.value.id)||!visibleTrack(input.value.id))return;await playTrack(input.value.id,queue);}updateDesktopPlayer();return;}
  if(c==='appearance'){state.appearance.player=normalizePlayer({...state.appearance.player,...input.value});await persistLocal(false);drawUnifiedPlayer();updateDesktopPlayer();return;}
  if(c==='equalizer'){if(p.source==='spotify')return;state.appearance.equalizer=normalizeEqualizer(input.value);visualizer.configureEqualizer(state.appearance.equalizer);await persistLocal(false);refreshEqualizerPanels();updateDesktopPlayer();return;}
  if(playbackSource==='spotify'&&spotify.status.connected){
    let action,value;const deviceId=spotify.playback?.device?.id||spotify.device;
    if(c==='toggle'){if(!p.canToggle)return;action=p.paused?'resume':'pause';}
    else if(c==='previous'||c==='next'){if(!(c==='next'?p.canNext:p.canPrevious))return;action=c;}
    else if(c==='seek'){if(!p.canSeek)return;action='seek';value=Math.max(0,Math.min(1,Number(input.value)||0))*spotify.playback.duration;}
    else if(c==='volume'){if(!p.canVolume)return;action='volume';value=Math.round(Math.max(0,Math.min(1,Number(input.value)||0))*100);}
    else if(c==='shuffle'){if(!p.canShuffle)return;action='shuffle';value=!p.shuffle;}
    else if(c==='repeat'){if(!p.canRepeat)return;action='repeat';value=p.repeat==='off'?'context':p.repeat==='context'?'track':'off';}
    if(action)await spotify.command({action,...(value===undefined?{}:{value}),deviceId});drawUnifiedPlayer();return;
  }
  if(c==='toggle'){if(listening.followRoom){if(synchronized.enabled)synchronized.stop();else await synchronized.start();}else if(currentId){if(audio.paused)await audio.play();else audio.pause();}else {const tracks=currentView==='local'?ownLocalTracks(state,team.user?.id):state.tracks;if(tracks.length)await playTrack(tracks[0].id,tracks.map(t=>t.id));else toast('Importiere zuerst einen Song.');}}
  else if(c==='previous'&&!listening.followRoom){if(audio.currentTime>3)audio.currentTime=0;else nextTrack(-1);}
  else if(c==='next')nextTrack(1);
  else if(c==='seek'&&p.canSeek&&Number.isFinite(audio.duration))audio.currentTime=Math.max(0,Math.min(1,Number(input.value)||0))*audio.duration;
  else if(c==='volume')audio.volume=Math.max(0,Math.min(1,Number(input.value)||0));
  else if(c==='shuffle'&&!listening.followRoom){shuffle=!shuffle;queueNavigator.reset();queueNavigator.commit(currentId);}
  else if(c==='repeat'&&!listening.followRoom)repeat=nextRepeat(repeat);
  if(qol){const prefs=qol.settings();prefs.repeat=repeat;prefs.shuffle=shuffle;if(qol.sleep.originalVolume==null)prefs.volume=audio.volume;if(['repeat','shuffle','volume'].includes(c))persistLocal(false).catch(fail);}drawUnifiedPlayer();updateDesktopPlayer();if(['seek','shuffle','repeat','next','previous','toggle'].includes(c))prepareNextAudio().catch(()=>{});
}
function refreshEqualizerPanels(){for(const panel of document.querySelectorAll('#dock-equalizer,#equalizer-settings')){panel.dataset.source=unifiedPlayback().source;panel.innerHTML=equalizerView(state.appearance.equalizer,unifiedPlayback().source);bindPlayerSettings(panel);}}
function bindPlayerSettings(root=document){
  visualizer.configureEqualizer(state.appearance.equalizer);
  for(const button of root.querySelectorAll('[data-player-skin]'))button.onclick=()=>playerCommand({command:'appearance',value:{skin:button.dataset.playerSkin}}).then(()=>{if(currentView==='player')render();}).catch(fail);
  for(const select of root.querySelectorAll('[data-player-setting]'))select.onchange=()=>playerCommand({command:'appearance',value:{[select.dataset.playerSetting]:select.value}}).catch(fail);
  for(const input of root.querySelectorAll('[data-eq],[data-eq-band]')){
    const change=()=>{if(unifiedPlayback().source==='spotify')return;const eq=state.appearance.equalizer;
      if(input.hasAttribute('data-eq-band')){eq.gains[Number(input.dataset.eqBand)]=Number(input.value);eq.preset='custom';const preset=input.closest('#dock-equalizer,#equalizer-settings')?.querySelector('[data-eq="preset"]');if(preset)preset.value='custom';}
      else if(input.dataset.eq==='preset'){if(!EQ_PRESETS[input.value])return;eq.gains=[...EQ_PRESETS[input.value].gains];eq.preset=input.value;eq.enabled=true;}
      else eq[input.dataset.eq]=input.type==='checkbox'?input.checked:Number(input.value);
      state.appearance.equalizer=normalizeEqualizer(eq);visualizer.configureEqualizer(eq);const output=input.parentElement?.querySelector('output');if(output)output.textContent=Number(input.value).toFixed(0);
    };
    input.oninput=change;input.onchange=async()=>{change();await persistLocal(false);refreshEqualizerPanels();updateDesktopPlayer();};
  }
}

